POST /v1/cases
request: {"id":"demo-nan","name":"demo-nan","suite_id":"demo-suite","kind":"unit","steps":[{"action":"run"}],"parameterization":{"axes":{"value":[NaN]}}}
status: 400
response: {
  "error": {
    "code": "validation_error",
    "message": "parameterization.axes.value[0] must be a scalar"
  }
}

